function ageParse(s){
  var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s).trim());
  if(!m) return { error:'日期格式应为 YYYY-MM-DD' };
  var y=+m[1], mo=+m[2], d=+m[3];
  var dt=new Date(Date.UTC(y,mo-1,d));
  if(isNaN(dt.getTime())|| dt.getUTCFullYear()!==y || dt.getUTCMonth()!==mo-1 || dt.getUTCDate()!==d) return { error:'非法日期' };
  return { error:null, t:dt.getTime() };
}
function ageDays(a,b){
  if(typeof a==='string'){ var pa=ageParse(a); a=pa.error?NaN:pa.t; }
  if(typeof b==='string'){ var pb=ageParse(b); b=pb.error?NaN:pb.t; }
  return Math.floor((b-a)/86400000);
}
function ageDiff(fromS, toS){
  var a=ageParse(fromS), b=ageParse(toS);
  if(a.error) return { error:a.error };
  if(b.error) return { error:b.error };
  if(b.t < a.t) return { error:'结束日期不能早于开始日期' };
  var d0=new Date(a.t), d1=new Date(b.t);
  var years=d1.getUTCFullYear()-d0.getUTCFullYear();
  var months=d1.getUTCMonth()-d0.getUTCMonth();
  var days=d1.getUTCDate()-d0.getUTCDate();
  if(days<0){ months--; var prev=new Date(Date.UTC(d1.getUTCFullYear(), d1.getUTCMonth(),0)); days+=prev.getUTCDate(); }
  if(months<0){ years--; months+=12; }
  return { error:null, years:years, months:months, days:days, totalDays:ageDays(a.t,b.t) };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ageParse:ageParse, ageDays:ageDays, ageDiff:ageDiff };
}
if (typeof window !== 'undefined') {
  window.AgeForgePure = { ageParse:ageParse, ageDays:ageDays, ageDiff:ageDiff };
}
